return [
  {json:{event_id:'c1',name:'Ana',email:'ANA@EXAMPLE.COM',date:'2026-11-01',people:'8',activities:'rafting',lodging:'',message:'grupo de amigos'}},
  {json:{event_id:'c2',name:'Luis',email:'luis@example.com',date:'',people:'6',activities:'barranquismo',lodging:'',message:'grupo de amigos'}},
  {json:{event_id:'c3',name:'Marta',phone:'+34 600 123 456',date:'2026-11-12',people:'4',activities:'rafting',lodging:'',message:'Solo actividad sin alojamiento.'}},
  {json:{event_id:'c4',name:'Pablo',email:'pablo@example.com',date:'2026-11-15',people:'5',activities:'senderismo',lodging:'',message:'No queremos hotel sin desayuno'}},
  {json:{event_id:'c5',name:'Eva',email:'eva@example.com',date:'2026-12-02',people:'20',activities:'team building',lodging:'',message:'Evento corporativo de empresa'}},
  {json:{event_id:'',name:'SinId',email:'sinid@example.com',date:'2026-12-10',people:'2',activities:'rafting',lodging:'',message:'amigos'}}
];

const LABELS={date:'fecha',people:'número de personas',activities:'actividades',lodging:'alojamiento',name:'nombre',contact:'contacto'};
const REQUIRED={despedida:['name','contact','date','people','activities'],amigos:['name','contact','date','people','activities'],familia:['name','contact','date','people','activities'],empresa:['name','contact','date','people','activities'],escolar:['name','contact','date','people','activities'],solo_actividad:['name','contact','date','people','activities'],pack_alojamiento:['name','contact','date','people','activities','lodging'],revision:['name','contact']};
const clean=v=>String(v??'').trim().replace(/\s+/g,' ');
const normEmail=v=>clean(v).toLowerCase();
const normPhone=v=>{const s=clean(v);if(!s)return '';return s.startsWith('+')?'+'+s.replace(/\D/g,''):s.replace(/\D/g,'');};
const classify=raw=>{const text=[raw.group_type,raw.message,raw.activities,raw.lodging].map(clean).join(' ').toLowerCase();if ([raw.group_type, raw.message, raw.activities, raw.lodging].some(value => /\b(?:sin(?:\s+necesidad\s+de)?|no\s+(?:queremos|necesitamos))\s+(?:alojamiento|hotel|hostal|casa rural)(?:\s+|[,;:]\s*)\S/.test(clean(value).toLowerCase()))) return 'revision';
const withoutLodgingText = text.replace(/\b(?:sin(?:\s+necesidad\s+de)?|no\s+(?:queremos|necesitamos))\s+(?:alojamiento|hotel|hostal|casa rural)\b/g, ' ');
const withoutLodging = withoutLodgingText !== text;
if (withoutLodging && /\b(?:alojamiento|hotel|hostal|casa rural)\b/.test(withoutLodgingText)) return 'revision';
const rules=[['despedida',/despedid/],['empresa',/empresa|team\s?building|corporativ/],['escolar',/escolar|colegio|instituto|alumn/],['familia',/familia|niñ|hijos?/],['pack_alojamiento',/alojamiento|hotel|hostal|casa rural|pack/],['solo_actividad',/solo actividad|actividad suelta|sin alojamiento/],['amigos',/amigos?|grupo/]];for(const [cat,rx] of rules)if(rx.test(text))return cat==='pack_alojamiento'&&withoutLodging?'solo_actividad':cat;return 'revision';};
const input=$input.all().map(i=>i.json.body??i.json);
return input.map(raw=>{
  const contact=clean(raw.email)||clean(raw.phone);
  if(!clean(raw.event_id)) return {json:{ok:false,status:'validation_failed',errors:['missing_event_id'],autonomous_send:false}};
  if(!clean(raw.name)||!contact) return {json:{ok:false,status:'validation_failed',errors:['missing_name_or_contact'],autonomous_send:false}};
  const category=classify(raw);
  const view={name:clean(raw.name),contact,date:clean(raw.date),people:clean(raw.people),activities:clean(raw.activities),lodging:clean(raw.lodging)};
  const missing=(REQUIRED[category]||REQUIRED.revision).filter(k=>!view[k]);
  const summary=[`Tipo: ${category}`,`Nombre: ${view.name||'N/D'}`,`Contacto: ${contact||'N/D'}`,`Fecha: ${view.date||'N/D'}`,`Personas: ${view.people||'N/D'}`,`Actividades: ${view.activities||'N/D'}`,`Alojamiento: ${view.lodging||'N/D'}`,`Faltan: ${missing.length?missing.map(x=>LABELS[x]||x).join(', '):'nada crítico'}`].join('\n');
  const prefix=clean(raw.name)||'Hola';
  const reply=missing.length?`${prefix}, gracias por contactar con Huescaventura. Para orientarte mejor sobre ${category}, antes necesitamos confirmar: ${missing.map(x=>LABELS[x]||x).join(', ')}. Este mensaje es un borrador para revisión humana y no se ha enviado.`:`${prefix}, gracias por contactar con Huescaventura. Tenemos la información básica para revisar tu solicitud de ${category}. Prepararemos la opción más adecuada y confirmaremos disponibilidad y condiciones antes de responderte. Este mensaje es un borrador para revisión humana y no se ha enviado.`;
  return {json:{ok:true,status:'prepared_for_human_review',event_id:clean(raw.event_id),identity:{email:normEmail(raw.email),phone:normPhone(raw.phone)},category,classification_review_required:category==='revision',missing_fields:missing,summary,reply_draft:reply,next_step:category==='revision'?'manual_classification_review':(missing.length?'request_missing_data':'human_review_quote_or_availability'),followup:{status:'pending_human_decision',autonomous_send:false},persistence_note:'Demo importable: deduplication/idempotency persistence must be bound to Airtable/Sheet/DB in client environment.'}};
});

const rows=$input.all().map(i=>i.json);
if(rows.length!==6) throw new Error(`expected 6 outputs, got ${rows.length}`);
const byId=Object.fromEntries(rows.filter(r=>r.event_id).map(r=>[r.event_id,r]));
const eq=(a,b,msg)=>{if(a!==b) throw new Error(`${msg}: expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);};
const ok=(v,msg)=>{if(!v) throw new Error(msg);};
eq(byId.c1.category,'amigos','c1 category');
eq(byId.c1.identity.email,'ana@example.com','c1 normalized email');
eq(byId.c1.missing_fields.length,0,'c1 missing');
eq(byId.c1.next_step,'human_review_quote_or_availability','c1 next step');
eq(byId.c2.category,'amigos','c2 category');
ok(byId.c2.missing_fields.includes('date'),'c2 must require date');
eq(byId.c2.next_step,'request_missing_data','c2 next step');
eq(byId.c3.category,'solo_actividad','c3 category');
eq(byId.c3.identity.phone,'+34600123456','c3 normalized phone');
eq(byId.c4.category,'revision','c4 ambiguous lodging negation');
eq(byId.c4.classification_review_required,true,'c4 review flag');
eq(byId.c4.next_step,'manual_classification_review','c4 next step');
eq(byId.c5.category,'empresa','c5 category');
const invalid=rows.find(r=>r.status==='validation_failed' && Array.isArray(r.errors) && r.errors.includes('missing_event_id'));
ok(!!invalid,'missing event_id case must be blocked');
for(const r of rows.filter(r=>r.ok)){
  eq(r.followup.autonomous_send,false,`${r.event_id} autonomous send`);
  ok(r.reply_draft.includes('no se ha enviado'),`${r.event_id} reply must disclose draft-only state`);
}
return [{json:{pass:true,cases:6,runtime:'n8n-code-node',autonomous_send:false}}];
